/// Password digit sprites (drawn by $D158): 6 digits at y = PASSWORD_DIGIT_Y,
/// x = PASSWORD_DIGIT_X + 8*i, 8x16 sprite tiles PASSWORD_DIGIT_TILE + 2*digit
/// (top) and +1 (bottom) from CHR bank 4 (sprite pattern table 0), sprite
/// palette group 2 of PAL_GAMEPLAY_SPR.
pub const PASSWORD_DIGIT_Y: u8 = 0x64;
pub const PASSWORD_DIGIT_X: u8 = 0x68;
pub const PASSWORD_DIGIT_TILE: u8 = 0x76;

/// Decode an `$A1BD` RLE stream into (ppu_addr, tile) writes. Semantics verified
/// against the ROM interpreter at $A1BD: FE lo hi sets the address AND the row
/// anchor; FD advances the anchor one row ($20) — literal writes do not move the
/// anchor; FC toggles +32 column-write mode; FB n copies the next n bytes
/// literally (the only way to write tiles $FB-$FF); FF ends.
pub fn decode_stream(stream: &[u8]) -> Vec<(u16, u8)> {
    let mut writes = Vec::new();
    let mut anchor = stream[0] as usize | (stream[1] as usize) << 8;
    let mut addr = anchor;
    let mut pos = 2;
    let mut inc32 = false;
    loop {
        let b = stream[pos];
        pos += 1;
        match b {
            0xFF => break,
            0xFE => { anchor = stream[pos] as usize | (stream[pos + 1] as usize) << 8; addr = anchor; pos += 2; }
            0xFD => { anchor += 0x20; addr = anchor; }
            0xFC => inc32 = !inc32,
            0xFB => { let n = stream[pos] as usize; pos += 1;
                for i in 0..n { writes.push((addr as u16, stream[pos + i])); addr += if inc32 { 32 } else { 1 }; }
                pos += n; }
            _ => { writes.push((addr as u16, b)); addr += if inc32 { 32 } else { 1 }; }
        }
    }
    writes
}

/// Decode an `$E866` map script blob into (ppu_addr, tile) writes.
/// FD/FE semantics match the engine: FE sets anchor + cursor, FD advances the
/// anchor one row and resets the cursor to it, literals advance only the cursor.
/// FC jumps are already resolved in the emitted blobs.
pub fn decode_script(script: &[u8], anchor: u16) -> Vec<(u16, u8)> {
    let mut writes = Vec::new();
    let mut pos = 0usize;
    let mut anchor = anchor;
    let mut addr = anchor;
    loop {
        let b = script[pos];
        pos += 1;
        match b {
            0xFF => break,
            0xFE => { anchor = script[pos] as u16 | (script[pos + 1] as u16) << 8; addr = anchor; pos += 2; }
            0xFD => { anchor += 0x20; addr = anchor; }
            0xFC => unreachable!("emitted scripts have FC jumps resolved"),
            _ => { writes.push((addr, b)); addr += 1; }
        }
    }
    writes
}
